import { chromium, expect, test } from "@playwright/test";
import { execFileSync } from "node:child_process";
import { createServer } from "node:http";
import { cp, mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";

// Real browser chrome events cannot be generated by page.evaluate or CDP DOM clicks.
// On Linux, run this regression under xvfb-run; XTest sends physical key events.
function invokeToolbarAction() {
  execFileSync(
    "python3",
    [
      "-c",
      `
import ctypes,ctypes.util,time
x=ctypes.CDLL(ctypes.util.find_library('X11'))
t=ctypes.CDLL(ctypes.util.find_library('Xtst'))
x.XOpenDisplay.argtypes=[ctypes.c_char_p];x.XOpenDisplay.restype=ctypes.c_void_p
x.XStringToKeysym.argtypes=[ctypes.c_char_p];x.XStringToKeysym.restype=ctypes.c_ulong
x.XKeysymToKeycode.argtypes=[ctypes.c_void_p,ctypes.c_ulong];x.XKeysymToKeycode.restype=ctypes.c_uint
x.XFlush.argtypes=[ctypes.c_void_p]
x.XCloseDisplay.argtypes=[ctypes.c_void_p]
t.XTestFakeKeyEvent.argtypes=[ctypes.c_void_p,ctypes.c_uint,ctypes.c_int,ctypes.c_ulong]
d=x.XOpenDisplay(None)
if not d: raise RuntimeError('No X11 display')
keys=[x.XKeysymToKeycode(d,x.XStringToKeysym(k)) for k in [b'Alt_L',b'Shift_L',b'y']]
for k in keys:t.XTestFakeKeyEvent(d,k,1,0)
x.XFlush(d);time.sleep(0.1)
for k in reversed(keys):t.XTestFakeKeyEvent(d,k,0,0)
x.XFlush(d);x.XCloseDisplay(d)
`,
    ],
    { stdio: "pipe" },
  );
}

test("未预授权网站时，真实工具栏动作获得 activeTab 并恢复已打开的侧边栏", async () => {
  test.skip(
    process.platform !== "linux" || !process.env.DISPLAY,
    "Requires Linux X11 (xvfb-run), libXtst and python3 for a real browser toolbar action.",
  );
  const server = createServer((_req, res) => {
    res.setHeader("Content-Type", "text/html; charset=utf-8");
    res.end(
      '<!doctype html><meta charset="utf-8"><title>未授权网页测试</title><main><h1>设备文档</h1><p>先创建通信接口，再初始化设备对象。</p></main>',
    );
  });
  await new Promise<void>((r) => server.listen(0, "127.0.0.1", r));
  const origin = `http://127.0.0.1:${(server.address() as { port: number }).port}`;
  const temp = await mkdtemp(join(tmpdir(), "reader-permission-regression-"));
  const extension = join(temp, "extension");
  await cp(resolve("dist"), extension, { recursive: true });
  const manifest = JSON.parse(
    await readFile(join(extension, "manifest.json"), "utf8"),
  );
  // Only add a shortcut for the real toolbar action; do not add any host permission.
  manifest.commands._execute_action = {
    suggested_key: { default: "Alt+Shift+Y" },
  };
  await writeFile(join(extension, "manifest.json"), JSON.stringify(manifest));
  const context = await chromium.launchPersistentContext(
    join(temp, "profile"),
    {
      channel: "chromium",
      headless: false,
      args: [
        `--disable-extensions-except=${extension}`,
        `--load-extension=${extension}`,
        "--no-sandbox",
      ],
      viewport: { width: 1000, height: 750 },
    },
  );
  try {
    const worker =
      context.serviceWorkers()[0] ||
      (await context.waitForEvent("serviceworker"));
    const extensionId = new URL(worker.url()).host;
    await worker.evaluate(() => {
      chrome.action.onClicked.addListener((tab) => {
        void chrome.storage.session.set({ testToolbarClick: tab.id });
      });
    });
    const page = await context.newPage();
    await page.goto(origin);
    const tabId = await worker.evaluate(async () => {
      const [tab] = await chrome.tabs.query({
        active: true,
        currentWindow: true,
      });
      return tab.id!;
    });
    const before = await worker.evaluate(
      async (id) => ({
        url: (await chrome.tabs.get(id)).url,
        permissions: await chrome.permissions.getAll(),
      }),
      tabId,
    );
    expect(before.url).toBeUndefined();
    expect(before.permissions.origins || []).toEqual([]);
    const panel = await context.newPage();
    await page.bringToFront();
    await panel.goto(`chrome-extension://${extensionId}/sidepanel.html`);
    await expect(panel.getByRole("alert")).toContainText(
      "尚未获得当前网页的读取权限",
    );
    await page.bringToFront();
    invokeToolbarAction();
    await expect
      .poll(() =>
        worker.evaluate(
          async () =>
            (await chrome.runtime.getContexts({ contextTypes: ["SIDE_PANEL"] }))
              .length,
        ),
      )
      .toBeGreaterThan(0);
    await expect
      .poll(() =>
        worker.evaluate(async (id) => (await chrome.tabs.get(id)).url, tabId),
      )
      .toBe(origin + "/");
    await expect(panel.getByText(/正文文字已读取/)).toBeVisible();
    expect(
      await worker.evaluate(() =>
        chrome.storage.session.get("testToolbarClick"),
      ),
    ).toEqual({ testToolbarClick: tabId });
    // activeTab is temporary; the action must not silently grant persistent site access.
    expect(
      (await worker.evaluate(() => chrome.permissions.getAll())).origins || [],
    ).toEqual([]);
    const second = await context.newPage();
    await second.goto(origin + "/second");
    await second.bringToFront();
    await expect(panel.getByRole("alert")).toContainText(
      "尚未获得当前网页的读取权限",
    );
    invokeToolbarAction();
    await expect(panel.getByText(/正文文字已读取/)).toBeVisible();
    expect(await panel.locator(".domain").innerText()).toBe("127.0.0.1");
    expect(
      (await worker.evaluate(() => chrome.permissions.getAll())).origins || [],
    ).toEqual([]);
  } finally {
    await context.close();
    await new Promise<void>((r) => server.close(() => r()));
    await rm(temp, { recursive: true, force: true });
  }
});
